if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$username=trim($_POST['username']??'');$password=$_POST['password']??'';if($name&&$username&&strlen($password)>=10){$st=$pdo->prepare("INSERT INTO admins(name,username,password_hash) VALUES(?,?,?)");try{$st->execute([$name,$username,password_hash($password,PASSWORD_DEFAULT)]);$done=true;$message='Admin account created. Delete setup_admin.php now for safety.';}catch(PDOException $e){$message='That admin username already exists.';}}else{$message='Use a name, username and password of at least 10 characters.';}}
